from pathlib import Path
import subprocess,json,re,collections,os
r=Path.home()/"CheshireAraPULP"; v=r/"target/sim/vcs"; out={}
def run(args):
 p=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,timeout=30)
 return {"rc":p.returncode,"output":p.stdout.strip()}
s=(v/"elaborate.log").read_text(errors="replace")
locs=collections.Counter(re.findall(r'Warning-\[SIOB\][^\n]*\n([^\n]+), (\d+)',s))
out["bounds_warning_locations"]=[{"file":str(Path(f).relative_to(r)),"line":int(n),"count":c} for (f,n),c in locs.items()]
for name in ["vector_helloworld.spm.elf","fmatmul.spm.elf","rvv_test_vstart_csrs.spm.elf"]:
 p=r/"sw/tests"/name
 dump=run(["/opt/riscv/bin/riscv64-unknown-elf-objdump","-d",str(p)])["output"].splitlines()
 selected=[]
 for i,l in enumerate(dump):
  if "mstatus" in l: selected.extend(dump[max(0,i-2):i+2])
 out[name]={"mstatus_context":selected[:45],"entry":run(["/opt/riscv/bin/riscv64-unknown-elf-objdump","-d","--start-address=0x10000000","--stop-address=0x10000110",str(p)])["output"]}
out["trace_head"]=(v/"trace_hart_0.log").read_text(errors="replace").splitlines()[:12]
out["models"]={p.name:{"size":p.stat().st_size} for p in (r/"target/sim/models").glob("*.v")}
out["core_cfg_source"]=str(r/".bender/git/checkouts/cva6-20c9d7cbe0dd6995/core/include/cv64a6_imafdcv_sv39_config_pkg.sv")
out["generated_sw_tools"]={str(p.relative_to(r)):p.exists() for p in [r/"sw/lib/libcheshire.a",r/"sw/boot/flash.spm.elf",r/".bender/.chs_deps"]}
out["compile_group_counts"]={"groups":(v/"compile.cheshire_soc.sh").read_text().count("vlogan -sverilog"),"full64":(v/"compile.cheshire_soc.sh").read_text().count("-full64")}
for name in ["vector_helloworld.spm.elf","fmatmul.spm.elf","rvv_test_vstart_csrs.spm.elf"]:
 out[name].pop("entry",None)
print(json.dumps(out,ensure_ascii=False,indent=2))
